hooks.command:
gjdc_sync() {
  s="$1"; d="${2:-$1}";
  if [ -d "$d" ]; then echo "gjdc: $d est un REPERTOIRE, pas un fichier — remplacement impossible." >&2; return 1; fi;
  mkdir -p "$(dirname "$d")" 2>/dev/null;
  raw="$d.gjdc-raw.$$"; tmp="$d.gjdc-tmp.$$";
  if gh api "repos/groupe-j/dev-conventions/contents/$s" --jq '.size, .content' > "$raw" 2>/dev/null && [ -s "$raw" ]; then
    attendu=$(head -n 1 "$raw");
    tail -n +2 "$raw" | base64 -d > "$tmp" 2>/dev/null;
    obtenu=$(wc -c < "$tmp" 2>/dev/null | tr -d " ");
    case "$attendu" in "" | *[!0-9]*) attendu=-1;; esac;
    if [ -s "$tmp" ] && [ "$obtenu" = "$attendu" ]; then
      rm -f "$raw";
      if mv -f "$tmp" "$d"; then return 0; fi;
      rm -f "$tmp";
      echo "gjdc: echec du remplacement de $d — le fichier existant est CONSERVE. Cible verrouillee, permissions, ou volume plein." >&2;
      return 1;
    fi;
  fi;
  rm -f "$raw" "$tmp";
  echo "gjdc: echec de synchro de $s vers $d — le fichier existant est CONSERVE (ni vide, ni tronque). Verifier gh auth status et le reseau." >&2;
  return 1;
};
gjdc_rc=0;
gjdc_sync CLAUDE_SHARED.md || gjdc_rc=1;
gjdc_home="${HOME:-$USERPROFILE}";
if [ -n "$gjdc_home" ]; then
  gjdc_sync chip-protocol.md "$gjdc_home/.claude/chip-protocol.md" || gjdc_rc=1;
else
  echo "gjdc: ni HOME ni USERPROFILE — chip-protocol.md NON distribue." >&2; gjdc_rc=1;
fi;
exit $gjdc_rc
